'use strict';
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons=[`<rect x="3" y="5" width="30" height="25" rx="4"/><path d="m12 14-4 4 4 4m12-8 4 4-4 4m-4-10-4 16"/>`,`<rect x="5" y="5" width="25" height="25" rx="2"/><circle cx="5" cy="5" r="3"/><circle cx="30" cy="5" r="3"/><circle cx="5" cy="30" r="3"/><circle cx="30" cy="30" r="3"/><path d="m13 25 5-15 5 15m-8-5h6"/>`,`<path d="M5 30V18h6v12m4 0V11h6v19m4 0V5h6v25M3 32h31"/>`,`<ellipse cx="18" cy="18" rx="16" ry="6" transform="rotate(35 18 18)"/><ellipse cx="18" cy="18" rx="16" ry="6" transform="rotate(-35 18 18)"/><ellipse cx="18" cy="18" rx="6" ry="16"/><circle cx="18" cy="18" r="2"/>`,`<path d="M5 6h22a4 4 0 0 1 4 4v12a4 4 0 0 1-4 4H15l-8 6v-6H5a4 4 0 0 1-4-4V10a4 4 0 0 1 4-4Z"/><path d="M9 13h14M9 19h9"/>`,`<path d="M18 4v28M4 18h28"/><circle cx="18" cy="18" r="14" stroke-dasharray="3 5"/>`];
const domains=[
{name:'编程开发',desc:'软件工程、AI、云计算',focus:['LLVM / Clang','前端工程','机器学习','云与基础设施'],source:'LLVM Documentation',url:'https://llvm.org/docs/',terms:[['LLVM','保留原名','编译器基础设施项目，涵盖中间表示与优化工具。'],['Clang','保留原名','LLVM 项目中的 C、C++ 和 Objective-C 编译器前端。'],['Sema','语义分析','Clang 中负责语义检查的组件名称，保留 Sema。'],['AST','抽象语法树','用树结构表达源代码的语法信息。'],['IR','中间表示','连接编译器前端与优化、代码生成阶段的表示。'],['Optimization pass','优化遍','对程序中间表示进行分析或变换的处理步骤。']]},
{name:'设计创作',desc:'产品、交互、视觉设计',focus:['产品与交互','视觉设计','设计系统','用户研究'],source:'Material Design',url:'https://m3.material.io/',terms:[['Affordance','可供性','物体或界面暗示的可操作方式。'],['Design token','设计令牌','命名并复用颜色、间距等设计决策。'],['Hierarchy','视觉层级','用对比、大小与位置建立信息优先级。'],['Prototype','原型','用来探索和验证产品交互的模型。'],['Accessibility','无障碍','让不同能力的人都能使用产品。'],['Feedback','反馈','使用户感知操作结果的界面响应。']]},
{name:'商业沟通',desc:'策略、营销、团队协作',focus:['产品策略','市场营销','创业与融资','团队协作'],source:'商业术语',url:'',terms:[['Go-to-market','市场进入策略','将产品带向目标客户的计划。'],['Retention','留存','用户在首次使用后继续使用产品的情况。'],['Runway','资金可支撑时长','在当前支出水平下现金可维持的时间。'],['Product-market fit','产品与市场契合','产品满足目标市场需求的程度。'],['Stakeholder','利益相关方','对项目有影响或受到项目影响的人。'],['Conversion','转化','用户完成预期行为的过程。']]},
{name:'科研学习',desc:'论文、讲座、研究方法',focus:['计算机科学','自然科学','学术报告','研究方法'],source:'学术术语',url:'',terms:[['Hypothesis','假设','有待证据检验的解释或预测。'],['Baseline','基线','用来比较实验方法的参照。'],['Ablation study','消融实验','通过移除组件分析其贡献。'],['Reproducibility','可复现性','在明确条件下重复获得结果的能力。'],['Peer review','同行评审','由相关领域研究者审查工作。'],['Methodology','研究方法','指导研究设计和实施的方法体系。']]},
{name:'日常交流',desc:'会议、播客、生活表达',focus:['日常会议','访谈播客','旅行文化','影视内容'],source:'常用表达',url:'',terms:[['Catch up','交流近况','了解彼此最近的情况。'],['Takeaway','主要收获','对一段讨论最值得记住的要点。'],['On the same page','达成共识','对当前情况有一致的理解。'],['Follow up','跟进','在初次交流后继续处理。'],['Wrap up','结束并总结','为讨论或活动收尾。'],['Sounds good','听起来不错','表示认可或同意。']]},
{name:'自定义领域',desc:'添加其他专业领域',focus:[],source:'通用词汇',url:'',terms:[['Context','上下文','理解话语所需的背景信息。'],['Terminology','术语','某个领域使用的专门词汇。'],['Definition','定义','对概念含义的明确说明。'],['Reference','参考资料','供查证和进一步学习的信息来源。']]}
];
const state={page:'start',domain:0,focus:'LLVM / Clang',custom:'',cache:null,progress:0,generating:false,paused:false,timer:null,settingsTab:0,theme:'dark',size:22,opacity:96,bilingual:true,originalFirst:false,dock:true,autoCache:true,connected:false,playing:false,tick:0,captionTimer:null};
const programmingExamples={
 '前端工程':[['Component','组件','封装界面与交互逻辑的可复用单元。'],['Hydration','水合','将服务端输出的页面连接到客户端交互逻辑。'],['Reconciliation','协调更新','比较界面变化并更新实际元素的过程。'],['Accessibility','无障碍','让不同能力的人都能使用界面。'],['Bundle','资源包','打包后交付给浏览器的代码资源。'],['State','状态','驱动界面呈现与交互的数据。']],
 '机器学习':[['Inference','推理','用已训练的模型生成预测或输出。'],['Embedding','嵌入','用向量表示文本或其他信息。'],['Fine-tuning','微调','在已有模型基础上继续训练。'],['Overfitting','过拟合','模型过度适应训练数据的现象。'],['Gradient','梯度','指导参数更新的变化方向。'],['Batch','批次','一次训练或推理处理的一组样本。']],
 '云与基础设施':[['Container','容器','封装应用与运行依赖的环境。'],['Orchestration','编排','管理多个服务实例的部署与运行。'],['Load balancing','负载均衡','将请求分配给多个实例。'],['Observability','可观测性','借助指标、日志和追踪理解系统状态。'],['Latency','延迟','完成一次操作所需要的等待时间。'],['Availability','可用性','服务保持可访问的程度。']]
};
const samples=[['今天，我们来看看 Clang 如何理解一段 C++ 代码。','Today, let’s look at how Clang understands a piece of C++ code.'],['解析器会构建 AST，而 Sema 负责检查代码的语义。','The parser builds the AST, while Sema checks the semantics.'],['接下来，LLVM 会对中间表示执行一系列优化。','Next, LLVM runs a sequence of optimizations on the intermediate representation.']];
let toastTimer;
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,2800)}
function go(page){location.hash=page;if(state.page===page)render()}
function pageTitle(eyebrow,title,sub,extra=''){return `<div class="intro"><div class="heading-row"><h1>${title}</h1>${extra}</div>${sub?`<p class="subtitle">${sub}</p>`:''}</div>`}
function render(){state.page=['start','knowledge','captions','settings'].includes(location.hash.slice(1))?location.hash.slice(1):'start';document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===state.page));$('#breadcrumb').innerHTML=`工作空间 <b>/</b> ${{start:'开始使用',knowledge:'知识空间',captions:'实时字幕',settings:'偏好设置'}[state.page]}`;$('#count').textContent=state.cache?'1':'0';$('#app').innerHTML=`<section class="page">${state.page==='start'?(state.generating?processPage():startPage()):state.page==='knowledge'?knowledgePage():state.page==='settings'?settingsPage():captionsPage()}</section>`;if(state.page==='start'&&state.generating)updateProgress();updateCaption()}
function startPage(){let d=domains[state.domain];return `${pageTitle('A LITTLE CONTEXT. A LOT MORE CLARITY.','选择内容领域','为转录与翻译添加专业词汇。','<div class="step-indicator"><i class="current"></i><i></i><i></i><span>1 / 3</span></div>')}<div class="domains" role="group" aria-label="选择内容领域">${domains.map((d,i)=>`<button class="domain ${i===state.domain?'selected':''}" data-domain="${i}" aria-pressed="${i===state.domain}"><span class="check" aria-hidden="true">✓</span><span class="icon" aria-hidden="true"><svg viewBox="0 0 36 36">${icons[i]}</svg></span><strong>${d.name}</strong><small>${d.desc}</small></button>`).join('')}</div><div class="focus-area"><div class="label-line">${state.domain===5?'领域名称':'细分方向'}<span>${state.domain===5?'例如：半导体制造、音乐制作':''}</span></div>${state.domain===5?`<input class="custom-input" id="custom" aria-label="自定义领域" placeholder="输入你感兴趣的领域…" maxlength="80" value="${esc(state.custom)}">`:`<div class="chips">${d.focus.map(f=>`<button class="chip ${f===state.focus?'selected':''}" data-focus="${f}" aria-pressed="${f===state.focus}">${f}</button>`).join('')}</div>`}</div><div class="setup-footer"><div class="hint">生成后自动保存到本地</div><button class="primary" data-action="generate" ${state.domain===5&&!state.custom.trim()?'disabled':''}>生成知识库 <span class="arrow">↗</span></button></div>`}
function processPage(){return `<div class="process"><div class="process-symbol working" aria-hidden="true">✳</div><h1>正在生成知识库</h1><p class="subtitle">${esc(state.domain===5?state.custom:state.focus)}</p><div class="progress-panel"><div class="progress-head"><span id="progress-label">正在准备</span><span id="percent">0%</span></div><div class="progress-track" role="progressbar" aria-label="生成进度" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><div id="progress-fill"></div></div>${[['查找参考资料','从文档与公开资料中建立上下文'],['整理术语与表达','保留专有名词，补充含义与译法'],['建立本地知识缓存','整理成可复用的知识文件']].map((s,i)=>`<div class="stage" data-stage="${i}"><span class="stage-num">${i+1}</span><div>${s[0]}<small>${s[1]}</small></div></div>`).join('')}</div><div class="source-ticker" id="source-ticker">正在准备资料…</div><div class="process-actions"><button class="small" data-action="pause-generation">${state.paused?'继续':'暂停'}</button><button class="small ghost" data-action="cancel-generation">取消</button></div></div>`}
function updateProgress(){if(!$('#progress-fill'))return;let p=Math.round(state.progress),stage=Math.min(2,Math.floor(p/34));$('#progress-fill').style.width=p+'%';$('.progress-track').setAttribute('aria-valuenow',p);$('#percent').textContent=p+'%';$('#progress-label').textContent=state.paused?'已暂停':'正在整理';$('.process-symbol').classList.toggle('working',!state.paused);document.querySelectorAll('.stage').forEach((el,i)=>{el.classList.toggle('active',i===stage);el.classList.toggle('done',i<stage);el.querySelector('.stage-num').textContent=i<stage?'✓':i+1});$('#source-ticker').textContent=['参考资料 · '+domains[state.domain].source,'术语、定义与上下文正在逐项整理…','knowledge / '+cacheSlug()+'.json'][stage]}
function cacheSlug(){return state.domain===0&&state.focus==='LLVM / Clang'?'llvm-clang':['programming','design','business','research','everyday','custom'][state.domain]}
function beginGeneration(){if(state.generating)return;state.progress=0;state.paused=false;state.generating=true;render();state.timer=setInterval(()=>{if(state.paused)return;state.progress=Math.min(100,state.progress+2);updateProgress();if(state.progress>=100){clearInterval(state.timer);state.generating=false;const d=domains[state.domain];state.cache={name:state.domain===5?state.custom:state.focus,domain:d.name,slug:cacheSlug(),source:state.domain===0&&state.focus!=='LLVM / Clang'?'技术术语':d.source,url:state.domain===0&&state.focus!=='LLVM / Clang'?'':d.url,entries:(state.domain===0&&programmingExamples[state.focus]||d.terms).map((t,i)=>({id:i,term:t[0],translation:t[1],meaning:t[2]})),example:true};go('knowledge');toast('知识库已生成')}},160)}
function knowledgePage(){if(!state.cache)return `${pageTitle('YOUR PERSONAL CONTEXT','知识空间','')}<div class="empty"><div class="process-symbol">▦</div><h2>还没有知识库</h2><p>添加一个领域，开始积累专业词汇。</p><button class="primary" data-go="start">选择领域 <span class="arrow">↗</span></button></div>`;let c=state.cache;return `${pageTitle('A SPACE THAT SPEAKS YOUR LANGUAGE',esc(c.name),'','<button class="small" data-go="start">＋ 新建知识库</button>')}<div class="result-banner"><div><h3>✓ 已保存到本地</h3><p>knowledge/${esc(c.slug)}.json</p></div><div class="stats"><div class="stat"><b>${c.entries.length}</b>术语</div></div></div><div class="section-toolbar"><h3>术语与表达 <span class="hint"> / ${esc(c.domain)}</span></h3><input class="search" id="search" aria-label="搜索术语" placeholder="搜索术语或译法…"></div><div class="term-grid" id="terms">${termCards('')}</div><div class="results-actions"><button class="ghost small" data-action="export">↓ 导出</button><button class="primary" data-go="captions">使用此知识库 <span class="arrow">→</span></button></div>`}
function termCards(query){const list=state.cache.entries.filter(e=>(e.term+e.translation+e.meaning).toLowerCase().includes(query.toLowerCase()));return list.length?list.map(e=>`<button class="term-card" data-term="${e.id}"><div class="term-top"><strong>${esc(e.term)}</strong><span class="tag">术语</span></div><p>${esc(e.translation)} · ${esc(e.meaning)}</p><small>${esc(state.cache.source)} <span style="float:right">↗</span></small></button>`).join(''):'<p class="subtitle">没有匹配的术语，试试其他关键词。</p>'}
function openTerm(id){const e=state.cache.entries.find(x=>x.id===id);const dialog=$('#detail');dialog.innerHTML=`<div class="dialog-top"><div><h2>${esc(e.term)}</h2></div><button class="ghost small" data-action="close-dialog" aria-label="关闭术语详情">✕</button></div><p>${esc(e.meaning)}</p><div class="field-label">字幕中的译法</div><input id="translation-edit" aria-label="字幕中的译法" maxlength="100" value="${esc(e.translation)}"><div class="field-label">参考来源</div>${state.cache.url?`<a class="source-link" href="${state.cache.url}" target="_blank" rel="noopener noreferrer">${esc(state.cache.source)} ↗</a>`:`<p>${esc(state.cache.source)}</p>`}<div class="dialog-actions"><button data-action="close-dialog">取消</button><button class="primary" data-save="${id}">保存修改</button></div>`;dialog.showModal()}
function segmented(key,options){return `<div class="segmented" role="group" aria-label="${key}">${options.map(([v,label])=>`<button data-setting="${key}" data-value="${v}" class="${String(state[key])===String(v)?'active':''}" aria-pressed="${String(state[key])===String(v)}">${label}</button>`).join('')}</div>`}
function row(title,desc,control){return `<div class="setting-row"><div>${title}${desc?`<p>${desc}</p>`:''}</div>${control}</div>`}
function settingsPage(){let panel='';if(state.settingsTab===0)panel=`<h3>字幕外观</h3>${row('字幕主题','',segmented('theme',[['dark','深色'],['light','浅色']]))}${row('字号','',`<div class="range-control"><input aria-label="字幕字号" id="font-size" type="range" min="16" max="32" value="${state.size}"><span id="font-value">${state.size}px</span></div>`)}${row('背景不透明度','',`<div class="range-control"><input aria-label="背景不透明度" id="opacity" type="range" min="50" max="100" value="${state.opacity}"><span id="opacity-value">${state.opacity}%</span></div>`)}${row('窗口位置','',segmented('dock',[[true,'底部停靠'],[false,'自由悬浮']]))}`;
if(state.settingsTab===1)panel=`<h3>语言与翻译</h3>${row('语言方向','','<span class="service-mark">英语 → 简体中文</span>')}${row('字幕内容','',segmented('bilingual',[[true,'双语'],[false,'仅中文']]))}${row('阅读顺序','',segmented('originalFirst',[[false,'中文在上'],[true,'英文在上']]))}`;
if(state.settingsTab===2)panel=`<h3>知识与存储</h3>${row('自动缓存知识','生成后保存到本地',`<button class="switch ${state.autoCache?'on':''}" role="switch" aria-label="自动缓存知识" aria-checked="${state.autoCache}" data-action="toggle-cache"></button>`)}${row('当前知识库',state.cache?esc(state.cache.name):'未选择',`<button class="small" data-go="${state.cache?'knowledge':'start'}">${state.cache?'查看知识':'开始创建'}</button>`)}${row('音频保存','','<span class="service-mark">不保存</span>')}`;
if(state.settingsTab===3)panel=`<h3>连接服务</h3><div class="connection"><div class="connection-head"><strong>OpenAI</strong><span class="service-mark">${state.connected?'已连接':'未连接'}</span></div><p>实时转录 + Luna 翻译</p><div class="key-placeholder">sk-••••••••••••••••••••••••</div><button class="small" data-action="connect">${state.connected?'重新连接':'连接'}</button></div><div class="connection"><div class="connection-head"><strong>Soniox</strong><span class="hint">可选服务</span></div><p>转录、说话人区分与翻译</p><button class="small" disabled style="margin-top:12px">待接入</button></div>`;
return `${pageTitle('MAKE IT FEEL LIKE YOU','偏好设置','')}<div class="settings-layout"><div class="settings-menu" aria-label="设置分类">${['字幕外观','语言与翻译','知识与存储','连接服务'].map((n,i)=>`<button data-settings-tab="${i}" class="${state.settingsTab===i?'active':''}" aria-pressed="${state.settingsTab===i}">${n}</button>`).join('')}</div><div><div class="settings-panel"><div class="settings-group">${panel}</div>${state.settingsTab<2?`<div class="settings-preview"><small>字幕预览</small><div id="settings-stage" class="${state.dock?'':'floating-preview'}">${captionBox()}</div></div>`:''}</div></div></div>`}
function captionBox(){return `<div class="caption-box"><div class="cap-meta"><span><span class="cap-dot">●</span>说话人 1</span><span>${state.playing?'转写中':state.tick?'已暂停':'准备就绪'}</span></div><div class="cap-copy"><div class="cap-zh"></div><div class="cap-en"></div></div></div>`}
function captionsPage(){return `${pageTitle('','实时字幕','','<button class="small" data-go="settings">字幕设置</button>')}<div class="session-toolbar"><div class="session-source"><span class="source-icon">▣</span><div><strong>系统音频</strong><small>英语 <span>→</span> 简体中文</small></div></div><button class="primary" data-action="play">${state.playing?'Ⅱ 暂停':'▷ 开始字幕'}</button></div><div class="session-context"><span class="status-pill ${state.playing?'listening':''}"><i></i>${state.playing?'正在聆听':state.tick?'已暂停':'就绪'}</span><button class="context-link" data-go="knowledge">${state.cache?esc(state.cache.name):'选择知识库'} <span>⌄</span></button><div class="layout-options">${segmented('dock',[[true,'停靠'],[false,'悬浮']])}</div></div><div class="video-stage ${state.dock?'':'floating'}"><div class="lecture"><small>LLVM DEVELOPERS’ MEETING</small><h2>Understanding the<br>Clang front end.</h2><div class="lecture-rule"></div><p>From source code to meaning.</p></div>${captionBox()}</div><div class="session-bottom"><span class="duration" id="duration">00:${String(state.tick%60).padStart(2,'0')}</span><button class="ghost small" data-action="restart" aria-label="重新播放">↺</button><span class="session-cost">本次费用 <strong>$0.00</strong></span></div>`}
function updateCaption(){const idx=Math.floor(state.tick/7)%samples.length;let [zh,en]=samples[idx];if(state.playing){let phase=state.tick%7;const end=Math.max(7,Math.round(zh.length*Math.min(1,(phase+2)/6)));const fullZh=zh;zh=zh.slice(0,end);if(/[A-Za-z+]/.test(fullZh[end]||''))zh=zh.replace(/[A-Za-z+]+$/,'');en=en.split(' ').slice(0,Math.max(5,Math.round(en.split(' ').length*Math.min(1,(phase+2)/5)))).join(' ')}document.querySelectorAll('.caption-box').forEach(box=>{box.classList.toggle('light',state.theme==='light');box.classList.toggle('zh-only',!state.bilingual);box.classList.toggle('original-first',state.originalFirst);box.style.backgroundColor=state.theme==='light'?`rgba(255,255,255,${state.opacity/100})`:`rgba(31,34,32,${state.opacity/100})`;box.querySelector('.cap-zh').style.fontSize=state.size+'px';box.querySelector('.cap-zh').textContent=zh;box.querySelector('.cap-en').textContent=en});if($('#duration'))$('#duration').textContent='00:'+String(state.tick%60).padStart(2,'0')}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;if(d.go){go(d.go);return}if(d.domain!==undefined){state.domain=Number(d.domain);state.focus=domains[state.domain].focus[0]||'';render();return}if(d.focus){state.focus=d.focus;render();return}if(d.term!==undefined){openTerm(Number(d.term));return}if(d.save!==undefined){const entry=state.cache.entries.find(x=>x.id===Number(d.save));const value=$('#translation-edit').value.trim();if(!value){$('#translation-edit').focus();return}entry.translation=value;$('#detail').close();render();toast('已保存');return}if(d.settingsTab!==undefined){state.settingsTab=Number(d.settingsTab);render();return}if(d.setting){state[d.setting]=d.value==='true'?true:d.value==='false'?false:d.value;render();return}switch(d.action){case'generate':beginGeneration();break;case'pause-generation':state.paused=!state.paused;b.textContent=state.paused?'继续':'暂停';updateProgress();break;case'cancel-generation':clearInterval(state.timer);state.generating=false;render();toast('已取消');break;case'close-dialog':$('#detail').close();break;case'export':{const blob=new Blob([JSON.stringify(state.cache,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=state.cache.slug+'.example.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出');break}case'toggle-cache':state.autoCache=!state.autoCache;render();break;case'connect':b.disabled=true;b.textContent='验证连接中…';setTimeout(()=>{state.connected=true;if(state.page==='settings')render();toast('连接成功')},1000);break;case'play':state.playing=!state.playing;clearInterval(state.captionTimer);if(state.playing)state.captionTimer=setInterval(()=>{state.tick++;updateCaption()},1000);render();break;case'restart':state.tick=0;updateCaption();toast('字幕已回到开头');break}});
document.addEventListener('input',e=>{if(e.target.id==='custom'){state.custom=e.target.value;const b=$('[data-action="generate"]');b.disabled=!state.custom.trim()}if(e.target.id==='search')$('#terms').innerHTML=termCards(e.target.value);if(e.target.id==='font-size'){state.size=Number(e.target.value);$('#font-value').textContent=state.size+'px';updateCaption()}if(e.target.id==='opacity'){state.opacity=Number(e.target.value);$('#opacity-value').textContent=state.opacity+'%';updateCaption()}});
window.addEventListener('hashchange',render);render();
